import {cpSync,mkdirSync,mkdtempSync,readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
const root=process.cwd(), work=mkdtempSync(join(root,'.git','b11-lock-owner-'));
cpSync(join(root,'src'),join(work,'src'),{recursive:true,dereference:false});
mkdirSync(join(work,'tests/helpers'),{recursive:true});
for(const name of ['test-database.ts','owned-test-directory.ts','test-database.test.ts'])writeFileSync(join(work,'tests/helpers',name),readFileSync(join(root,'tests/helpers',name)));
const helper=join(work,'tests/helpers/test-database.ts');
let code=readFileSync(helper,'utf8');
const needle='throw new Error(`Test database cleanup failed; retained: ${dir}; ${String(cause)}`, {cause});';
if(code.split(needle).length!==2)throw Error('Unexpected diagnostic hook');
code='import {spawnSync as diagnosticSpawn} from "node:child_process";\n'+code.replace(needle,'const query = diagnosticSpawn("powershell.exe",["-NoProfile","-NonInteractive","-File",'+JSON.stringify(join(root,'.git/Get-MemoryFileLockOwners.ps1'))+',path],{encoding:"utf8",windowsHide:true,timeout:25000});\nprocess.stderr.write("LOCK_OWNER="+JSON.stringify({pid:process.pid,path,status:query.status,out:query.stdout,error:query.stderr,spawnFailure:query.error?.message,signal:query.signal})+"\\n");\n'+needle);
writeFileSync(helper,code);
writeFileSync(join(work,'bunfig.toml'),'[test]\ncoverage=false\ntimeout=30000\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts'))+']\n');
const runs=[];
for(let i=0;i<8;i++){
 const result=Bun.spawnSync([process.execPath,'test','src/presentation/cli/commands/export.test.ts'],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:45000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 runs.push({iteration:i+1,exit:result.exitCode,output});
 console.log(JSON.stringify({iteration:i+1,exit:result.exitCode,ownerLines:output.split('\n').filter(x=>x.startsWith('LOCK_OWNER='))}));
 if(output.includes('LOCK_OWNER='))break;
}
writeFileSync('.git/b11-lock-owner-repro.json',JSON.stringify({cwd:work,runs,probeSource:readFileSync('.git/b11-lock-owner-repro.ts','utf8'),querySource:readFileSync('.git/Get-MemoryFileLockOwners.ps1','utf8')},null,2)+'\n');

