param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
public static class MemoryLockQuery {
 [StructLayout(LayoutKind.Sequential)] public struct UniqueProcess { public int Id; public System.Runtime.InteropServices.ComTypes.FILETIME Started; }
 [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)] public struct ProcessInfo {
  public UniqueProcess Process;
  [MarshalAs(UnmanagedType.ByValTStr, SizeConst=256)] public string Name;
  [MarshalAs(UnmanagedType.ByValTStr, SizeConst=64)] public string Service;
  public uint Type; public uint Status; public uint Session;
  [MarshalAs(UnmanagedType.Bool)] public bool Restartable;
 }
 [DllImport("rstrtmgr.dll", CharSet=CharSet.Unicode)] public static extern int RmStartSession(out uint session, uint flags, string key);
 [DllImport("rstrtmgr.dll", CharSet=CharSet.Unicode)] public static extern int RmRegisterResources(uint session, uint files, string[] paths, uint applications, IntPtr apps, uint services, IntPtr names);
 [DllImport("rstrtmgr.dll")] public static extern int RmGetList(uint session, out uint needed, ref uint count, [In,Out] ProcessInfo[] info, ref uint reasons);
 [DllImport("rstrtmgr.dll")] public static extern int RmEndSession(uint session);
}
'@
$sessionId = [uint32]0
$rc = [MemoryLockQuery]::RmStartSession([ref]$sessionId,0,[Guid]::NewGuid().ToString('N'))
if($rc -ne 0) { throw "RmStartSession failed: $rc" }
try {
 $rc = [MemoryLockQuery]::RmRegisterResources($sessionId,1,@($Path),0,[IntPtr]::Zero,0,[IntPtr]::Zero)
 if($rc -ne 0) { throw "RmRegisterResources failed: $rc" }
 $needed=[uint32]0; $count=[uint32]0; $reasons=[uint32]0
 $rc=[MemoryLockQuery]::RmGetList($sessionId,[ref]$needed,[ref]$count,$null,[ref]$reasons)
 if($rc -ne 0 -and $rc -ne 234) { throw "RmGetList size failed: $rc" }
 $owners=@()
 if($needed -gt 0) {
  $info=New-Object 'MemoryLockQuery+ProcessInfo[]' $needed
  $count=$needed
  $rc=[MemoryLockQuery]::RmGetList($sessionId,[ref]$needed,[ref]$count,$info,[ref]$reasons)
  if($rc -ne 0) { throw "RmGetList failed: $rc" }
  $owners=@($info | Select-Object @{Name='pid';Expression={$_.Process.Id}},Name,Type,Status)
 }
 @{path=$Path;owners=$owners;status=$rc} | ConvertTo-Json -Compress -Depth 5
} finally { [void][MemoryLockQuery]::RmEndSession($sessionId) }

