import {readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import ts from 'typescript';
const packet=JSON.parse(readFileSync('.git/b11-lock-owner-repro.json','utf8'));
const path=join(packet.cwd,'src/infrastructure/database/connection.ts');
const source=readFileSync(path,'utf8');
const ast=ts.createSourceFile(path,source,ts.ScriptTarget.Latest,true);
const node=ast.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='closeDatabase');
if(!node)throw Error('Missing close function');
const body=source.slice(node.pos,node.end);
if(body.split('db.close();').length!==2)throw Error('Unexpected close expression');
const runs=[];
try{
 writeFileSync(path,source.slice(0,node.pos)+body.replace('db.close();','db.close(true);')+source.slice(node.end));
 for(let i=0;i<8;i++){
  const result=Bun.spawnSync([process.execPath,'test','src/presentation/cli/commands/export.test.ts'],{cwd:packet.cwd,stdout:'pipe',stderr:'pipe',timeout:45000});
  const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
  runs.push({iteration:i+1,exit:result.exitCode,output});
  console.log(JSON.stringify({iteration:i+1,exit:result.exitCode,errors:output.split('\n').filter(x=>x.startsWith('error:')||x.startsWith('LOCK_OWNER='))}));
  if(result.exitCode!==0)break;
 }
}finally{writeFileSync(path,source);}
writeFileSync('.git/b11-strict-close-probe.json',JSON.stringify({cwd:packet.cwd,runs,scope:'Only closeDatabase in the already generated snapshot used strict db.close(true). Original project source was unchanged; generated connection source restored.',probeSource:readFileSync('.git/b11-strict-close-probe.ts','utf8')},null,2)+'\n');

