const ast=ts.createSourceFile(path,source,ts.ScriptTarget.Latest,true);
const node=ast.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='closeDatabase');
if(!node)throw Error('Missing close function');
const body=source.slice(node.pos,node.end);if(body.split('db.close();').length!==2)throw Error('Unexpected close');
const strict=source.slice(0,node.pos)+body.replace('db.close();','db.close(true);')+source.slice(node.end);
const runs=[];
try{
 writeFileSync(helper,readFileSync('tests/helpers/test-database.ts'));
 for(let round=0;round<12;round++)for(const mode of (round%2?[true,false]:[false,true])){
  writeFileSync(path,mode?strict:source);
  const result=Bun.spawnSync([process.execPath,'test','src/presentation/cli/commands/export.test.ts','--test-name-pattern','sets exit code 1 when database does not exist'],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:15000});
