  runs.push({round:round+1,strict:mode,exit:result.exitCode,output});
  console.log(JSON.stringify({round:round+1,strict:mode,exit:result.exitCode}));
 }
}finally{writeFileSync(path,source);writeFileSync(helper,originalHelper);}
const summary=[false,true].map(strict=>({strict,runs:runs.filter(x=>x.strict===strict).length,failures:runs.filter(x=>x.strict===strict&&x.exit!==0).length}));
writeFileSync('.git/b11-close-comparison.json',JSON.stringify({cwd:work,runtime:Bun.version,runs,summary,probeSource:readFileSync('.git/b11-close-comparison.ts','utf8'),scope:'Alternating normal/strict close in generated connection source only. Production source unchanged and generated originals restored.'},null,2)+'\n');console.log(JSON.stringify(summary));

