import {readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
const work=JSON.parse(readFileSync('.git/b11-lock-owner-repro.json','utf8')).cwd;
const path=join(work,'src/presentation/cli/commands/export.test.ts'), original=readFileSync(path,'utf8');
const source=original.replaceAll('\r\n','\n');
const helper=join(work,'tests/helpers/test-database.ts'), originalHelper=readFileSync(helper,'utf8');
if(source.split('afterEach(() => {').length!==2||source.split('    testDb.cleanup();').length!==2)throw Error('Unexpected teardown');
const candidate=source.replace('afterEach(() => {','afterEach(async () => {').replace('    testDb.cleanup();','    await new Promise(resolve => setImmediate(resolve));\n    testDb.cleanup();');
const runs=[];
try{
 writeFileSync(helper,readFileSync('tests/helpers/test-database.ts'));
 for(let round=0;round<8;round++)for(const yieldBeforeClose of (round%2?[true,false]:[false,true])){
  writeFileSync(path,yieldBeforeClose?candidate:source);
  const result=Bun.spawnSync([process.execPath,'test','src/presentation/cli/commands/export.test.ts'],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:30000});
  const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
  runs.push({round:round+1,yieldBeforeClose,exit:result.exitCode,output});
  console.log(JSON.stringify({round:round+1,yieldBeforeClose,exit:result.exitCode}));
 }
}finally{writeFileSync(path,original);writeFileSync(helper,originalHelper);}
const summary=[false,true].map(yieldBeforeClose=>({yieldBeforeClose,runs:runs.filter(x=>x.yieldBeforeClose===yieldBeforeClose).length,failures:runs.filter(x=>x.yieldBeforeClose===yieldBeforeClose&&x.exit!==0).length}));
writeFileSync('.git/b11-yield-comparison.json',JSON.stringify({cwd:work,runtime:Bun.version,runs,summary,probeSource:readFileSync('.git/b11-yield-comparison.ts','utf8'),scope:'Alternating original/one-event-loop-yield teardown in generated export-test source. Production source unchanged and generated originals restored.'},null,2)+'\n');console.log(JSON.stringify(summary));

