import {readFileSync,writeFileSync,lstatSync,realpathSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
const logs=['.git/b11-boundary-windows.txt','.git/b11-lock-owner-unverified.json','.git/b11-lock-owner-repro.json','.git/b11-yield-comparison.json'];
const names=new Set(logs.flatMap(path=>[...readFileSync(path,'utf8').matchAll(/memory-export-cmd-[A-Za-z0-9]+/g)].map(m=>m[0])));
const parent=realpathSync(tmpdir()), records=[];
for(const name of names){
 const dir=join(parent,name), stat=lstatSync(dir,{bigint:true,throwIfNoEntry:false});
 if(!stat){records.push({dir,status:'already absent'});continue;}
 const marker=join(dir,'.memory-test-owner.json'), ms=lstatSync(marker,{throwIfNoEntry:false});
 if(!stat.isDirectory()||stat.isSymbolicLink()||realpathSync(dir)!==dir||dirname(dir)!==parent||!ms?.isFile()||ms.isSymbolicLink()||ms.nlink!==1){records.push({dir,status:'retained - identity or marker shape not verified'});continue;}
 const owner=JSON.parse(readFileSync(marker,'utf8'));
 if(owner.project!=='memory-nexus'||owner.dir!==dir||owner.device!==stat.dev.toString()||owner.inode!==stat.ino.toString()||!Number.isSafeInteger(owner.pid)||owner.pid<=0){records.push({dir,status:'retained - marker identity not verified'});continue;}
 let stopped=false;
 try{process.kill(owner.pid,0);}catch(error){if(error.code==='ESRCH')stopped=true;}
 if(!stopped){records.push({dir,status:'retained - owner PID absent status not proved'});continue;}
 rmSync(dir,{recursive:true,force:false});records.push({dir,owner,status:'reclaimed - observed allocation, stopped PID and exact marker identity verified'});
}
writeFileSync('.git/b11-reclaimed-observed.json',JSON.stringify({logs,records,script:readFileSync('.git/b11-reclaim-observed.mjs','utf8')},null,2)+'\n');
console.log(JSON.stringify(records.map(({dir,status})=>({dir,status}))));

