for(const input of [...diagnostic.sourceInputs,...mutations.sourceInputs])assert(hash(input.path)===input.sourceHash,'Stale '+input.path);
assert(mutations.records.length===8&&mutations.records.every((r:any)=>r.status==='KILLED'&&r.exit===1&&!r.recovery.some((x:any)=>x.status.startsWith('retained'))),'Invalid mutation proof');
const repeat=read('.git/b11-yield-verify.json');
assert(repeat.runs.length===5&&repeat.runs.every((r:any)=>r.exit===0&&r.output.includes('59 pass')),'Repeat failed');
