for(const [label,path,count] of outputs)assert(readFileSync(path!,'utf8').includes(count!)&&readFileSync(path!,'utf8').includes('0 fail'),'Failed '+label);
const changed=['tests/helpers/test-database.test.ts','src/presentation/cli/commands/export.test.ts'];
