 const row=manifest.files.find((x:any)=>x.path===path), file=catalog.files.find(x=>x.path===path)!;
 row.sourceHash=file.sourceHash;
 row.metricApplicability={status:'incomplete - current source diagnostic or acceptance gap',sourceHash:file.sourceHash,evidence:path===changed[0]?metricsPath:packetPath,reason:path===changed[0]?'Windows diagnostic has 58/70 branches (82.85%); other metrics exceed 95%. No exclusion approved. Final instrumenter and independent review remain pending.':'Export teardown now yields one event-loop turn; existing args length assertion justifies a TypeScript non-null assertion. Prior metric evidence is invalidated; final Tier S applicability/coverage remains open.'};
}
assert(catalog.files.length===448&&validateInventory(catalog,manifest).length===0,'Inventory invalid');
save(root+'executable-catalog.json',catalog);save(root+'quality-classifications.json',manifest);
const item=ledger.items.find((x:any)=>x.id==='B11.1');
assert(item.status==='active'&&ledger.current_item==='B11.1','Unexpected restart item');
item.evidence=[...new Set([...item.evidence,packetPath,metricsPath,mutationsPath])];
item.progress={
 implemented:'Marker boundary regressions and export teardown event-loop yield. Existing ownership guards and bounded synchronous retry API unchanged.',
 verified_scope:'Current Windows 59 pass/160 assertions; Linux 58 pass/one Windows skip/154 assertions, explicit existing quality timeout 15000 ms. Expanded targeted typecheck passes. Both helpers remain 100% direct-Istanbul diagnostics; eight deliberate guard/lifecycle/retry faults killed.',
 repeat_scope:'Paired generated export test: synchronous teardown failed with EBUSY 2/8; event-loop yield failed 0/8. Five later Windows grouped runs passed 59 tests each at explicit 15000 ms. Final source differs from those repeats only by a TypeScript non-null assertion after an existing length assertion; final current-source Windows/Linux checks pass.',
