save(root+'work-items.json',ledger);
const paths=['tests/helpers/test-database.ts','tests/helpers/owned-test-directory.ts',...changed,'tests/infrastructure/database/repositories/friction-repository.test.ts','src/infrastructure/database/connection.ts','tests/test-setup.ts','bunfig.toml'];
const packet={item_id:'B11.1',status:'active',recorded_at:new Date().toISOString(),base_revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),sourceInputs:paths.map(path=>({path,sourceHash:hash(path)})),checks:[...outputs.map(([label,path])=>({label,command:'bun test --timeout 15000 tests/helpers/test-database.test.ts src/presentation/cli/commands/export.test.ts tests/infrastructure/database/repositories/friction-repository.test.ts',exit:0,output:readFileSync(path!,'utf8')})),{label:'expanded targeted types',command:'bunx tsc --project .git/b11-tsconfig.json',configuration:read('.git/b11-tsconfig.json'),exit:0,output:readFileSync('.git/b11-yield-types.txt','utf8')}],
