import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/', read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const hash=(p:string)=>sourceHash(readFileSync(p,'utf8'));
const assert=(x:unknown,m:string)=>{if(!x)throw Error(m);};
const current=discoverInventory(process.cwd()), catalog=read(root+'executable-catalog.json'), manifest=read(root+'quality-classifications.json');
assert(JSON.stringify(current)===JSON.stringify(catalog)&&validateInventory(current,manifest).length===0,'Stale inventory');
const path=root+'evidence/B11.1-boundaries-runtime.json', packet=read(path);
for(const input of [...packet.sourceInputs,...packet.artifacts])assert(hash(input.path)===input.sourceHash,'Stale '+input.path);
const diagnostic=read(root+'evidence/B11.1-driver-metrics.json'), coverage=createCoverageMap(diagnostic.rawCoverage);
for(const input of diagnostic.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale diagnostic');
for(const file of diagnostic.files)assert(JSON.stringify(coverage.fileCoverageFor(resolve(file.path)).toSummary().data)===JSON.stringify(file.metrics),'Bad metrics');
assert(diagnostic.files.at(-1).metrics.branches.covered===58&&diagnostic.files.at(-1).metrics.branches.total===70,'Driver scope changed');
const mutations=read(root+'evidence/B11.1-decision-mutations.json');
for(const input of mutations.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale mutations');
assert(mutations.records.length===8&&mutations.records.every((r:any)=>r.status==='KILLED'&&r.exit===1),'Bad mutation proof');
const ledger=read(root+'work-items.json'), ids=new Map<string,any>(ledger.items.map((x:any)=>[x.id,x])), done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(ids.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of ids.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert(ids.size===218&&ids.size===ledger.items.length,'Duplicate or missing task');for(const id of ids.keys())visit(id);
assert(ids.get('B11.1').status==='active'&&ids.get('B04').status==='blocked'&&ids.get('B05').status==='pending','Premature gate acceptance');
packet.validation={command:'bun .git/b11-boundaries-validate.ts',exit:0,source:readFileSync('.git/b11-boundaries-validate.ts','utf8'),result:'Live 448-file/two-package catalog, source and artifact hashes, raw diagnostic summaries, eight mutation outcomes and 218-item acyclic ledger reconciled. B11.1 remains active.',inventoryOutput:readFileSync('.git/b11-boundaries-inventory.txt','utf8')};
writeFileSync(path,JSON.stringify(packet,null,2)+'\n');console.log(packet.validation.result);
